<script setup lang="ts">
import { computed } from 'vue'
import { ArcElement, Chart as ChartJS, Tooltip } from 'chart.js'
import { Doughnut } from 'vue-chartjs'
import type { CategoryTotal } from '@/domain/services/statistics'
import { formatCents } from '@/domain/services/money'

ChartJS.register(ArcElement, Tooltip)

const props = defineProps<{ items: CategoryTotal[] }>()
const colors = ['#1677ff', '#20a162', '#ff7a45', '#8b5cf6', '#eab308', '#06b6d4', '#ef4444', '#64748b', '#f472b6', '#14b8a6']
const totalCents = computed(() => props.items.reduce((sum, item) => sum + item.amountCents, 0))
const data = computed(() => ({
  labels: props.items.map((item) => item.name),
  datasets: [{
    data: props.items.map((item) => item.amountCents / 100),
    backgroundColor: props.items.map((_, index) => colors[index % colors.length]),
    borderColor: '#fff',
    borderWidth: 2,
    hoverOffset: 4,
  }],
}))
const options = computed(() => ({
  responsive: true,
  maintainAspectRatio: false,
  cutout: '62%',
  animation: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? false as const : { duration: 250 },
  plugins: {
    legend: { display: false },
    tooltip: { callbacks: { label: (context: { label?: string; parsed: number }) => `${context.label ?? ''} ${formatCents(Math.round(context.parsed * 100))}` } },
  },
}))
</script>

<template>
  <div v-if="items.length" class="donut" role="img" :aria-label="`支出分类占比，共${items.length}个分类`">
    <div class="donut-canvas">
      <Doughnut :data="data" :options="options" />
      <div class="donut-center"><span>总支出</span><strong class="money">{{ formatCents(totalCents) }}</strong></div>
    </div>
    <div class="donut-legend" role="list">
      <div v-for="(item, index) in items" :key="item.categoryId" role="listitem">
        <i :style="{ backgroundColor: colors[index % colors.length] }" aria-hidden="true" />
        <span>{{ item.name }}</span>
        <small>{{ (item.ratio * 100).toFixed(1) }}%</small>
      </div>
    </div>
  </div>
  <p v-else class="empty">本期暂无支出数据</p>
</template>

