.range-nav button { display: inline-flex; min-height: 48px; align-items: center; justify-content: center; border: 0; border-radius: 13px; background: transparent; color: var(--color-text-secondary); }
.range-nav .range-current { min-width: 0; gap: 7px; color: var(--color-primary); }
.range-current strong { overflow: hidden; color: var(--color-text); font-size: 17px; text-overflow: ellipsis; white-space: nowrap; }
.totals { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); padding: 16px; background: #1357b7; color: white; }
.totals div { display: flex; min-width: 0; flex-direction: column; gap: 5px; }
.totals div:last-child { align-items: flex-end; border-left: 1px solid rgb(255 255 255 / 24%); }
.totals span { color: rgb(255 255 255 / 74%); font-size: 13px; }
.totals strong { max-width: 100%; overflow-wrap: anywhere; font-size: clamp(16px, 4.5vw, 21px); }
.totals .income { color: #baf3d4; }
.totals .expense { color: #ffd1bd; }
.report-card { padding: 16px; }
.report-card h2 { margin: 0 0 14px; font-size: 18px; }
.empty-report { display: grid; min-height: 320px; place-items: center; align-content: center; color: var(--color-text-secondary); text-align: center; }
.empty-report p { margin: 14px 0 0; }
.picker-mode { margin-bottom: 18px; }
.picker-page-nav { display: grid; grid-template-columns: 48px 1fr 48px; align-items: center; margin-bottom: 12px; text-align: center; }
.picker-page-nav button { display: grid; width: 48px; height: 48px; place-items: center; border: 0; border-radius: 50%; background: transparent; color: var(--color-text-secondary); }
.picker-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.picker-grid button { min-height: 48px; padding: 0 3px; border: 0; border-radius: 12px; background: var(--color-surface-muted); color: var(--color-text-secondary); font-size: 14px; }
.picker-grid button.selected { background: var(--color-primary); color: white; font-weight: 700; }
@media (max-width: 359px) { .picker-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
</style>
